import { IdGenerator } from '../../application/ports/IdGenerator';
import { ProjectRepository } from '../../domain/repositories/ProjectRepository';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { UserRepository } from '../../domain/repositories/UserRepository';
import { UuidIdGenerator } from '../identity/UuidIdGenerator';
import { InMemoryProjectRepository } from '../persistence/InMemoryProjectRepository';
import { InMemoryTaskRepository } from '../persistence/InMemoryTaskRepository';
import { InMemoryUserRepository } from '../persistence/InMemoryUserRepository';

export interface Dependencies {
  users: UserRepository;
  projects: ProjectRepository;
  tasks: TaskRepository;
  ids: IdGenerator;
}

export function createInMemoryDependencies(): Dependencies {
  return {
    users: new InMemoryUserRepository(),
    projects: new InMemoryProjectRepository(),
    tasks: new InMemoryTaskRepository(),
    ids: new UuidIdGenerator(),
  };
}

=====SOURCE-END=====

